/* mail-reader R2, R11: an Outlook message read from its compound file (build/requirements/mail-reader.md). Each MSG
 * is generated by ./fixtures.mjs's compound-file writer when the test runs. */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readMessage, attachmentBytes, detectMail } from "../../../src/mail-reader/index.mjs";
import * as F from "./fixtures.mjs";

const SPEC = {
  subject: "Contract amendment", fromName: "Ada Lane", fromAddress: "ada@example.org", messageId: "<msg-1@example.org>",
  body: "Please find the amendment attached.", date: "2026-10-06T16:30:00Z",
  recipients: [{ name: "Clerk", address: "clerk@example.gov" }, { name: "Ben", address: "ben@example.org", kind: 2 }],
  attachments: [{ name: "amendment.pdf", mime: "application/pdf", data: F.concat("%PDF-1.4\n", "x".repeat(5000)) }],
};

test("R2 a generated MSG with a body and an attachment answers the same fields an EML does", async () => {
  const bytes = F.msg(SPEC);
  assert.equal(detectMail(bytes), "msg");
  const a = await readMessage(bytes);
  assert.equal(a.ok, true);
  assert.equal(a.format, "msg");
  assert.deepEqual(
    { from: a.headers.from, to: a.headers.to, cc: a.headers.cc, subject: a.headers.subject, message_id: a.headers.message_id, date_utc: a.headers.date_utc },
    { from: "Ada Lane <ada@example.org>", to: "Clerk <clerk@example.gov>", cc: "Ben <ben@example.org>", subject: "Contract amendment", message_id: "<msg-1@example.org>", date_utc: "2026-10-06T16:30:00.000Z" },
  );
  assert.equal(a.body.text, "Please find the amendment attached.");
  assert.deepEqual(a.attachments.map((x) => [x.index, x.name_stated, x.type_stated, x.size, x.cut]), [[0, "amendment.pdf", "application/pdf", 5009, true]]);
  const cut = await attachmentBytes(bytes, 0);
  assert.deepEqual(cut.bytes, SPEC.attachments[0].data);
});

test("R2 an MSG's transport headers give its Received hops and automatic-mail facts", async () => {
  const transport = "Received: from b by c; Tue, 6 Oct 2026 09:30:02 -0700\r\nReceived: from a by b; Tue, 6 Oct 2026 09:30:01 -0700\r\nAuthentication-Results: c; spf=pass\r\nReturn-Path: <>\r\nDate: Tue, 6 Oct 2026 09:30:00 -0700\r\n";
  const a = await readMessage(F.msg({ ...SPEC, transport }));
  assert.deepEqual(a.headers.received, ["from b by c; Tue, 6 Oct 2026 09:30:02 -0700", "from a by b; Tue, 6 Oct 2026 09:30:01 -0700"]);
  assert.deepEqual(a.headers.authentication_results, ["c; spf=pass"]);
  assert.equal(a.headers.return_path, "<>");
  assert.equal(a.headers.date, "Tue, 6 Oct 2026 09:30:00 -0700");
});

test("R2 an HTML-only MSG reads its cleaned text; a hidden image is listed inline; an embedded message is listed and counted", async () => {
  const a = await readMessage(F.msg({
    subject: "s", html: '<p>Hello <img src="cid:i1"></p>', attachments: [
      { name: "i.png", mime: "image/png", data: "png", cid: "i1" },
      { name: "fwd.msg", embedded: { subject: "Forwarded", body: "inner" } },
    ],
  }));
  assert.equal(a.body.text, "Hello");
  assert.equal(a.body.from, "html");
  assert.deepEqual(a.attachments.map((x) => [x.type_stated, x.inline, x.cut]), [["image/png", true, true], ["message/rfc822", false, false]]);
  assert.equal(a.nesting_depth, 2);
  const r = await attachmentBytes(F.msg({ subject: "s", attachments: [{ name: "fwd.msg", embedded: { subject: "f" } }] }), 0);
  assert.equal(r.ok, false);
  assert.equal(r.reason, "MAIL_ATTACHMENT_NOT_CUT");
});

test("R11 a truncated MSG returns a stated failure and the call does not throw", async () => {
  const whole = F.msg(SPEC);
  for (const cut of [600, Math.floor(whole.length / 2), whole.length - 100]) {
    const r = await readMessage(whole.subarray(0, cut));
    assert.equal(r.ok, false, `cut at ${cut}`);
    assert.equal(r.reason, "MAIL_MSG_CONTAINER_BAD");
    assert.equal(typeof r.detail, "string");
  }
});

test("R11 a compound file that is not a message is refused as not a message", async () => {
  const r = await readMessage(F.cfb({ WordDocument: F.bytes("not mail") }));
  assert.equal(r.ok, false);
  assert.equal(r.reason, "MAIL_NOT_A_MESSAGE");
});
